export function mountWalkControls(host,p,context){for(const[k,v]of Object.entries(meshWalkDefaults))if(p[k]===undefined)p[k]=structuredClone(v);const fieldsMap=new Map();const save=()=>{for(const[key,v]of fieldsMap){v.input.value=p[key];v.output.textContent=p[key];}mode.value=p.walkMode;context.save();draw()};const button=(label,fn,parent=host)=>{const b=document.createElement('button');b.type='button';b.className='pill';b.textContent=label;b.onclick=fn;parent.append(b);return b},field=(parent,key,label,min,max,step=1)=>{const wrap=document.createElement('label');wrap.style.display='block';wrap.textContent=label;const input=document.createElement('input');input.type='range';input.min=min;input.max=max;input.step=step;input.value=p[key];input.setAttribute('aria-label',label);const output=document.createElement('output');output.textContent=p[key];input.oninput=()=>{p[key]=Number(input.value);output.textContent=input.value;save()};wrap.append(input,output);parent.append(wrap);fieldsMap.set(key,{input,output});return input};const tip=document.createElement('p');tip.textContent='Choose a walk, adjust the sliders, or drag a joint. Dragging pauses the gait for posing; scene travel has its own control. The classic walker stays in the Animation library.';host.append(tip);const preset=document.createElement('select');preset.setAttribute('aria-label','Walking style');for(const[name,label]of [['natural','Natural'],['careful','Careful over rubble'],['brisk','Brisk'],['idle','Stand and breathe']]){const o=document.createElement('option');o.value=name;o.textContent=label;preset.append(o)}host.append(preset);button('Apply walking style',()=>{Object.assign(p,structuredClone(walkPresets[preset.value||'natural']));if(preset.value!=='idle')p.walkMode='walk';save();context.refresh?.()});const mode=document.createElement('select');mode.setAttribute('aria-label','Walk or pose');for(const[name,label]of [['walk','Walking'],['idle','Standing'],['pose','Pose / drag joints']]){const o=document.createElement('option');o.value=name;o.textContent=label;mode.append(o)}mode.value=p.walkMode;mode.onchange=()=>{p.walkMode=mode.value;save()};host.append(mode);button('Turn around',()=>{p.walkFacing*=-1;save()});const canvas=document.createElement('canvas');canvas.width=canvas.height=420;canvas.style.cssText='width:100%;max-width:420px;background:#44464a;touch-action:none;border:1px solid #777';canvas.setAttribute('aria-label','Drag character joints to pose');host.append(canvas);const joint=document.createElement('select');joint.setAttribute('aria-label','Joint to move');for(const name of walkJointNames){const o=document.createElement('option');o.value=name;o.textContent=labels[name];joint.append(o)}host.append(joint);const values=document.createElement('div');host.append(values);function jointFields(){values.replaceChildren();const key=joint.value||'hip';p.walkJointOffsets[key]??=[0,0];for(let i=0;i<2;i++){const label=document.createElement('label');label.textContent=labels[key]+' '+(i?'up/down':'left/right');const input=document.createElement('input');input.type='number';input.value=p.walkJointOffsets[key][i];input.step=2;input.setAttribute('aria-label',label.textContent);input.oninput=()=>{p.walkJointOffsets[key][i]=Number(input.value)||0;save()};label.append(input);values.append(label)}}joint.onchange=jointFields;jointFields();button('Reset all joint positions',()=>{p.walkJointOffsets={};jointFields();save()});field(host,'walkCycleRate','Walking pace',.1,2,.05);field(host,'walkStepLength','Step length',25,340,5);field(host,'walkLift','Foot lift',0,160,2);field(host,'walkStance','Time on the ground',.4,.85,.01);field(host,'walkTorsoLean','Lean forward',-15,35,1);field(host,'walkArmSwing','Arm swing',0,45,1);button('Fast preview detail',()=>{p.walkMeshColumns=4;p.walkMeshRows=8;save()});button('High mesh detail',()=>{p.walkMeshColumns=12;p.walkMeshRows=24;save()});const detail=document.createElement('details');detail.innerHTML='<summary>Fine movement and mesh detail</summary>';host.append(detail);for(const row of [['walkHipBob','Hip rise/fall',0,30,1],['walkHipSway','Hip side motion',0,25,1],['walkHipRoll','Hip tilt amount',0,12,1],['walkTorsoTwist','Chest turn',0,15,1],['walkHeadNod','Head movement',0,15,1],['walkElbowBend','Elbow fold',0,70,1],['walkWristRoll','Wrist movement',0,30,1],['walkFootRoll','Heel/toe roll',0,35,1],['walkCoatFlutter','Coat movement',0,30,1],['walkBreath','Breathing',0,10,.5],['walkHeadSize','Head size',.6,1.5,.05],['walkFootSize','Boot size',.6,1.5,.05],['walkHeadAngle','Head angle',-45,45,1],['walkFrontFootAngle','Near boot angle',-45,45,1],['walkBackFootAngle','Far boot angle',-45,45,1],['walkBodyWidth','Body width',.5,1.5,.05],['walkLimbWidth','Limb width',.5,1.6,.05],['walkGroundSlope','Ground slope',-.4,.4,.01],['walkThighLength','Thigh length',130,240,2],['walkShinLength','Lower leg length',130,240,2],['walkMeshColumns','Mesh across each part',2,18,1],['walkMeshRows','Mesh along each part',3,28,1],['walkTorchTipX','Beam attachment left/right',0,1,.01],['walkTorchTipY','Beam attachment up/down',0,1,.01],['walkPosePhase','Position in step',0,1,.01]])field(detail,...row);const replace=document.createElement('select');replace.setAttribute('aria-label','Character part to replace');for(const name of Object.keys(meshWalkDefaults.walkPartRects)){const o=document.createElement('option');o.value=name;o.textContent=name==='torcharm'?'Torch forearm':name;replace.append(o)}detail.append(replace);const partCanvas=document.createElement('canvas');partCanvas.width=300;partCanvas.height=260;partCanvas.style.cssText='display:block;width:100%;max-width:300px;background:#50565b;touch-action:none';partCanvas.setAttribute('aria-label','Drag blue and gold attachment points on the selected body part');detail.append(partCanvas);let partHandle=null;const partInfo=document.createElement('p');partInfo.textContent='For a replacement limb, drag the blue start and gold end dots to its joints. No code is needed.';detail.append(partInfo);function attachment(){const name=replace.value||'torso';return p.walkPartAnchors[name]||{start:name==='torcharm'?[.18,.12]:[.5,.06],end:name==='torcharm'?[.78,.8]:[.5,.94]}}function drawCalibration(){const c=partCanvas.getContext('2d');c.clearRect(0,0,300,260);const im=getWalkPartImage(context.images,replace.value||'torso',p);if(!im)return;c.drawImage(im,0,0,300,260);if(['head','boot'].includes(replace.value)){partInfo.textContent='Use the head/foot joints and size/angle sliders for this part.';return;}partInfo.textContent='Drag blue start and gold end points to align a replacement limb.';const anchors=attachment();for(const[key,color]of [['start','#91e4ff'],['end','#ffdf75']]){c.fillStyle=color;c.beginPath();c.arc(anchors[key][0]*300,anchors[key][1]*260,7,0,Math.PI*2);c.fill();}}replace.onchange=drawCalibration;partCanvas.onpointerdown=e=>{if(['head','boot'].includes(replace.value))return;const r=partCanvas.getBoundingClientRect(),u=(e.clientX-r.left)/r.width,v=(e.clientY-r.top)/r.height,a=attachment();partHandle=Math.hypot(u-a.start[0],v-a.start[1])<Math.hypot(u-a.end[0],v-a.end[1])?'start':'end';partCanvas.setPointerCapture?.(e.pointerId);};partCanvas.onpointermove=e=>{if(!partHandle)return;const r=partCanvas.getBoundingClientRect(),name=replace.value||'torso';p.walkPartAnchors[name]=structuredClone(attachment());p.walkPartAnchors[name][partHandle]=[Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];save()};partCanvas.onpointerup=partCanvas.onpointercancel=()=>{partHandle=null;save()};button('Reset this part attachment',()=>{delete p.walkPartAnchors[replace.value||'torso'];save()},detail);button('Replace this body part…',()=>{const name=replace.value||'torso';context.replace('walkPart'+name[0].toUpperCase()+name.slice(1))},detail);button('Replace complete parts sheet…',()=>context.replace('walkAtlas'),detail);button('Save this walk preset',()=>{const parameters=Object.fromEntries(Object.keys(meshWalkDefaults).map(k=>[k,structuredClone(p[k])])),blob=new Blob([JSON.stringify({schema:'regaarder-animation-instance-v1',effectId:'natural-mesh-walk',parameters,playback:playbackDefaults,duration:8},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='walking-preset.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});const loadAlignment=document.createElement('input');loadAlignment.type='checkbox';loadAlignment.setAttribute('aria-label','Also load saved part alignment');const alignmentLabel=document.createElement('label');alignmentLabel.textContent='Also load saved part alignment';alignmentLabel.append(loadAlignment);host.append(alignmentLabel);const presetFile=document.createElement('input');presetFile.type='file';presetFile.accept='.json';presetFile.setAttribute('aria-label','Load walking preset');presetFile.onchange=async()=>{try{const data=JSON.parse(await presetFile.files[0].text());if(data.schema!=='motion-walk-preset-v1'&&!(data.schema==='regaarder-animation-instance-v1'&&data.effectId==='natural-mesh-walk'))throw Error('Choose a natural walking preset');const next=validateWalkParameters(data.parameters);const bindings=p.walkPartBindings,rects=p.walkPartRects,anchors=p.walkPartAnchors;Object.assign(p,next);p.walkPartBindings=bindings;if(!loadAlignment.checked){p.walkPartRects=rects;p.walkPartAnchors=anchors;}save();context.refresh?.();}catch(e){status.textContent=e.message}};const status=document.createElement('p');host.append(presetFile,status);let current,selected=null,origin=performance.now(),lastTime=0;function draw(){drawCalibration();const c=canvas.getContext('2d');c.clearRect(0,0,420,420);c.fillStyle='#62676b';c.fillRect(0,0,420,420);c.strokeStyle='#aaa';c.beginPath();c.moveTo(0,395);c.lineTo(420,395);c.stroke();current=paintMeshWalk(c,lastTime,context.images,[0,0,420,420],p);if(current){for(const[name,pos]of Object.entries(current.joints)){c.fillStyle=name===selected?'#ffe580':'#95d7e9';c.beginPath();c.arc(...pos,name===selected?5:3,0,Math.PI*2);c.fill();}}}canvas.onpointerdown=e=>{const r=canvas.getBoundingClientRect(),point=[(e.clientX-r.left)/r.width*420,(e.clientY-r.top)/r.height*420];if(!current)return;const closest=Object.entries(current.joints).sort((a,b)=>Math.hypot(a[1][0]-point[0],a[1][1]-point[1])-Math.hypot(b[1][0]-point[0],b[1][1]-point[1]))[0];if(Math.hypot(closest[1][0]-point[0],closest[1][1]-point[1])>24)return;selected=closest[0];p.walkPosePhase=((current.pose.phase%1)+1)%1;p.walkMode='pose';mode.value='pose';joint.value=selected;canvas.setPointerCapture?.(e.pointerId);jointFields();draw()};canvas.onpointermove=e=>{if(!selected)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*1000,y=(e.clientY-r.top)/r.height*1000,offsets={...p.walkJointOffsets,[selected]:[0,0]},base=meshWalkPose(0,{...p,walkJointOffsets:offsets}).joints[selected];p.walkJointOffsets[selected]=[(p.walkFacing<0?1000-x:x)-base[0],y-base[1]];jointFields();save()};canvas.onpointerup=()=>{selected=null;save()};canvas.onpointercancel=canvas.onpointerup;draw();function tick(now){if(!canvas.isConnected)return;lastTime=(now-origin)/1000;if(p.walkMode!=='pose'&&!selected&&canvas.offsetParent!==null)draw();requestAnimationFrame(tick)}if(typeof requestAnimationFrame==='function')requestAnimationFrame(tick);return {draw,canvas,joint};}
